INSERT INTO [tblGlobalSettings] ([SettingId], [SettingCategory], [SettingName], [SettingValue], [ValueType], [ValidationRule], [SettingDescription], [SortOrder], [CreationDate], [ModifiedDate]) VALUES (5, 'General', 'Site Slogan', 'Download your free Classic ASP CMS today!', 'text', NULL, 'The site slogan is simply a "sub-heading" for your website. The slogan generally appears as a smaller-sized text along side the larger more emphasized ''Site Name''. Depending on your website''s layout, this may or may not appear in the Heading of each page and in customer email inquiries.', 2, '2/21/2007 5:41:05 PM', '7/3/2007 3:37:32 PM');
INSERT INTO [tblGlobalSettings] ([SettingId], [SettingCategory], [SettingName], [SettingValue], [ValueType], [ValidationRule], [SettingDescription], [SortOrder], [CreationDate], [ModifiedDate]) VALUES (6, 'General', 'Site Keywords', 'classic asp cms content management system vbscript jscript asp3.0', 'textarea', 'simple', 'A comma separated list of general, site-wide keywords to be included in meta tags for every page in the site. Meta tags are visible to search engines.', 6, '2/21/2007 5:41:11 PM', '1/8/2007 8:41:48 PM');
